import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be positive")
    data = []
    start_time = time.time()
    while time.time() - start_time < duration:
        if platform.system() == "Windows":
            cmd = ["wmic", "cpu", "get", "loadpercentage"]
        else:
            cmd = ["top", "-bn1"]
        try:
            output = subprocess.check_output(cmd, shell=True).decode()
        except Exception:
            output = ""
        if platform.system() == "Windows":
            usage = output.strip().split('\n')[1].strip()
        else:
            lines = output.split('\n')
            if len(lines) > 2:
                cpu_line = lines[2]
                parts = cpu_line.split()
                if len(parts) > 8:
                    usage = parts[8].replace(',', '.')
                else:
                    usage = "0"
            else:
                usage = "0"
        try:
            usage_float = float(usage)
        except ValueError:
            usage_float = 0.0
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime())
        data.append({"timestamp": timestamp, "cpu_usage": usage_float})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(data, f)
        return LOGFILE_PATH
    except IOError:
        return None

